 'matrix-cell':e=>{const from=D.districts.find(d=>d.id===e.dataset.from),to=D.districts.find(d=>d.id===e.dataset.to);const edge=D.edges.find(x=>x[0]===from.id&&x[1]===to.id);state.archSelected=from.id;document.getElementById('module-summary').innerHTML=moduleSummary();document.getElementById('matrix-detail').textContent=from.id===to.id?`The diagonal is intentionally excluded. Intra-module imports are not shown in this matrix.`:`${from.name} → ${to.name}: ${edge?.[2]||0} observed import statements. ${from.id==='domain'&&to.id==='storage'?'These 3 imports violate AR-001.':'Select the module to explore its source files.'}`;},
