 'new-rule':()=>addRule(),'rule-detail':e=>ruleDetail(e.dataset.id),'save-rule':()=>{const from=document.getElementById('rule-from').value,to=document.getElementById('rule-to').value;if(from===to){toast('Choose two different modules.');return;}if(D.rules.some(r=>r.from===from&&r.to===to)){toast('A rule already exists for that module direction.');return;}const count=D.edges.find(e=>e[0]===from&&e[1]===to)?.[2]||0;const r={id:'USR-'+String(state.customRules.length+1).padStart(3,'0'),title:D.districts.find(d=>d.id===from).name+' must not import '+D.districts.find(d=>d.id===to).name,from,to,status:count?'Violation':'Passing',count,detail:document.getElementById('rule-rationale').value.trim()||'User-defined intended boundary for the sample graph.'};state.customRules.push(r);D.rules.push(r);save();closeModal();state.archTab='rules';render();toast('Boundary rule saved and evaluated against the sample graph.');},
